using Servicio.RetazoMarket.Business.DTOs.Producto;using Servicio.RetazoMarket.DataManagment.Models;
namespace Servicio.RetazoMarket.Business.Mappers;
public static class ProductoBusinessMapper { public static ProductoDataModel ToDataModel(CrearProductoRequest r,decimal precio)=>new(){id_linea=r.id_linea,prod_nombre=r.prod_nombre.Trim(),prod_peso=r.prod_peso,prod_descripcion=r.prod_descripcion.Trim(),colores=r.colores.Clone(),costo_mat_prim=r.costo_mat_prim,costo_mano_obra=r.costo_mano_obra,porcentaje_margen_ganancia=r.porcentaje_margen_ganancia,porcentaje_gastos_fijos=r.porcentaje_gastos_fijos,porcentaje_gastos_operativos=r.porcentaje_gastos_operativos,precio_base=precio,es_personalizable=r.es_personalizable.Trim().ToUpperInvariant(),stock_actual=0,tiene_descuentos="N",prod_estado=r.prod_estado.Trim().ToUpperInvariant()};public static ProductoDataModel ToDataModel(ActualizarProductoRequest r,decimal precio,int stock,string tieneDescuentos)=>new(){id_producto=r.id_producto,id_linea=r.id_linea,prod_nombre=r.prod_nombre.Trim(),prod_peso=r.prod_peso,prod_descripcion=r.prod_descripcion.Trim(),colores=r.colores.Clone(),costo_mat_prim=r.costo_mat_prim,costo_mano_obra=r.costo_mano_obra,porcentaje_margen_ganancia=r.porcentaje_margen_ganancia,porcentaje_gastos_fijos=r.porcentaje_gastos_fijos,porcentaje_gastos_operativos=r.porcentaje_gastos_operativos,precio_base=precio,es_personalizable=r.es_personalizable.Trim().ToUpperInvariant(),stock_actual=stock,tiene_descuentos=tieneDescuentos,prod_estado=r.prod_estado.Trim().ToUpperInvariant()};public static ProductoResponse ToResponse(ProductoDataModel m)=>new(){id_producto=m.id_producto,id_linea=m.id_linea,prod_nombre=m.prod_nombre,prod_peso=m.prod_peso,prod_descripcion=m.prod_descripcion,colores=m.colores.Clone(),costo_mat_prim=m.costo_mat_prim,costo_mano_obra=m.costo_mano_obra,porcentaje_margen_ganancia=m.porcentaje_margen_ganancia,porcentaje_gastos_fijos=m.porcentaje_gastos_fijos,porcentaje_gastos_operativos=m.porcentaje_gastos_operativos,precio_base=m.precio_base,es_personalizable=m.es_personalizable,stock_actual=m.stock_actual,tiene_descuentos=m.tiene_descuentos,prod_estado=m.prod_estado,linea_nombre=m.Linea?.lin_nombre};public static decimal CalcularPrecio(decimal material,decimal manoObra,decimal margen,decimal gastosFijos,decimal gastosOperativos){var costoBase=material+manoObra;var total=costoBase+(costoBase*gastosFijos/100m)+(costoBase*gastosOperativos/100m);return decimal.Round(total/(1m-margen/100m),2,MidpointRounding.AwayFromZero);}}
